1:// Read-only retained-call/source diagnosis. No conformance invocation, repair, retry or event admission.
2:import assert from 'node:assert/strict';import fs from 'node:fs/promises';import {join} from 'node:path';
3:import {loadRuntime} from './public-support.mjs';
4:const N=import.meta.dirname,read=async n=>JSON.parse(await fs.readFile(join(N,n),'utf8')),save=(n,v)=>fs.writeFile(join(N,n),JSON.stringify(v,null,2)+'\n',{flag:'wx'});
5:const identity=await read('selected-core.json'),{product,abg}=await loadRuntime(identity.installedRoot),hash=product.sha256Canonical;
6:const failure=await read('setup-failure.json'),transport=await read('setup-conformance-hello-world.jsonl'),call=transport.invocation,request=call.invocation.request;
7:const {admissionAuthority,...resources}=call.resources,expectedKeys=['kind','schemaVersion','packet','conformanceLaw','declaredInventory','declarationCatalog'].sort(),observedKeys=Object.keys(resources).sort();
8:const extraKeys=observedKeys.filter(k=>!expectedKeys.includes(k)),missingKeys=expectedKeys.filter(k=>!observedKeys.includes(k));assert.deepEqual(extraKeys,['artifactTruth']);assert.deepEqual(missingKeys,[]);
9:const expectedLaw={ref:'law://abiogenesis/validator/gtl-program@5',digest:hash({ref:'law://abiogenesis/validator/gtl-program@5'})};assert.deepEqual(request.conformanceLaw,expectedLaw);assert.deepEqual(resources.conformanceLaw,expectedLaw);
10:const binding=(await read('setup-bind-stdout.json')).receipt.ownerOutput.value.binding,selection=admissionAuthority.basis.boundEnvironment;assert.deepEqual(selection.prefix,failure.closeHandoff.prefix);assert.deepEqual(selection.workspaceBinding,binding);
11:const projection=abg.projectExactPrefixWorkspaceEnvironment(failure.closeHandoff.prefix,binding);assert.equal(projection.kind,'exact_prefix_workspace_environment');assert.deepEqual(resources.artifactTruth,projection.artifactTruth);
12:const coord=(ref,value)=>({ref,digest:hash(value)}),sort=xs=>[...xs].sort((a,b)=>a.ref.localeCompare(b.ref)||a.digest.localeCompare(b.digest));
13:assert.deepEqual(request.program,coord(resources.packet.program.programRef,resources.packet.program));assert.equal(resources.packet.program.programRef,'program://abiogenesis/conformance/hello-world@5');
14:assert.equal(resources.packet.kind,'conformance_evaluate_packet');assert.equal(resources.packet.schemaVersion,'5.0.0');assert.equal(resources.packet.memberKey,'gtl_program');assert.equal(resources.declaredInventory.length,11);
15:const inventory=sort(resources.declaredInventory.map(p=>coord(p.moduleRef,p)));assert.deepEqual(request.inventoryBasis,{kind:'declared_inventory',inventory});
16:const {catalog,catalogView}=resources.declarationCatalog;assert.deepEqual(sort(catalog.boundPublications.map(p=>coord(p.moduleRef,p))),inventory);
17:assert.deepEqual(resources.declaredInventory.find(p=>p.moduleRef===resources.packet.publication.moduleRef),resources.packet.publication);assert.deepEqual(resources.packet.publication.programs.find(p=>p.programRef===request.program.ref),resources.packet.program);
18:const catalogReceipt=(await read('setup-catalog-stdout.json')).receipt,viewReceipt=(await read('setup-catalog-view-stdout.json')).receipt;
19:assert.equal(catalogReceipt.ownerOutput.value.catalog.digest,catalog.basisDigest);assert.equal(viewReceipt.ownerOutput.value.view.digest,catalogView.viewDigest);
20:assert.deepEqual(call.invocation.invocationAuthority.slots.product_set,projection.productInstalls.map(product.productInstallCoordinate));assert.deepEqual(call.invocation.invocationAuthority.slots.workspace_binding,binding);assert.deepEqual(call.invocation.invocationAuthority.slots.dependency_lock,{ref:projection.resolvedProductLock.lockId,digest:projection.resolvedProductLock.lockDigest});assert.equal(call.invocation.invocationAuthority.slots.actor.actor.ref,projection.workspaceAuthorityBasis.authorizedActorRef);
21:const {admissionAuthority:removed,...scoped}=call.resources;assert.equal(admissionAuthority.basis.resourceScope.resourcesDigest,hash(scoped));assert.equal(admissionAuthority.authority.approval.value.scopeDigest,product.admissionAuthorityScope(admissionAuthority.basis).digest);
22:const plan=await read('resource-plan.json'),before=await fs.stat(plan.eventLogPath),bytes=await fs.readFile(plan.eventLogPath),after=await fs.stat(plan.eventLogPath);assert.equal(before.ino,after.ino);assert.equal(before.dev,after.dev);assert.equal(before.size,after.size);assert.equal(before.mtimeMs,after.mtimeMs);assert.deepEqual(bytes,await fs.readFile(join(N,'failure-native-prefix.jsonl')));assert.equal(product.sha256Bytes(bytes),failure.closeHandoff.prefix.prefixDigest);
23:const lockPath=join(plan.lockNamespace,`${after.dev}-${after.ino}.lock`);let lockPresent=false;try{await fs.stat(lockPath);lockPresent=true;}catch(e){if(e.code!=='ENOENT')throw e;}assert.equal(lockPresent,false);
24:await save('causal-bindings.json',{status:'FIRST_FAILURE_LOCALIZED_WITHOUT_RETRY',fault:(await read('setup-conformance-hello-world-stdout.json')).receipt.failure.fault,ownerBoundary:{wrapper:'withAdmissionAuthority strips only admissionAuthority, authenticates resource digest/grants and reconstructs boundEnvironment; owner receives that separately',expectedKeys,observedKeys,extraKeys,missingKeys,otherInitialPredicateInputsValid:true,decisiveCause:'artifactTruth is an extra caller field rejected by exact keys before Program conformance evaluation'},law:{actual:request.conformanceLaw,expected:expectedLaw,equal:true},packet:{kind:resources.packet.kind,schemaVersion:resources.packet.schemaVersion,memberKey:resources.packet.memberKey,program:request.program,programInPublication:true,publicationInInventory:true},inventory:{declaredCount:inventory.length,requestEquality:true,catalogEquality:true,coordinates:inventory},selection:{actual:selection,currentPrefixAndBindingEqual:true,callerArtifactTruthEqualsFreshReadOnlyOwnerProjection:true,artifactTruthDigest:hash(resources.artifactTruth),limit:'Equal content does not legalize a field absent from this owner resource contract'},authority:{actor:projection.workspaceAuthorityBasis.authorizedActorRef,workspaceBinding:binding,productSet:call.invocation.invocationAuthority.slots.product_set,dependencyLock:call.invocation.invocationAuthority.slots.dependency_lock,resourceDigestMatches:true,scopeDigestMatches:true},catalog:catalogReceipt.ownerOutput.value.catalog,catalogView:viewReceipt.ownerOutput.value.view,remainingSemanticUncertainty:'Owner declaration closure and validateProgram are downstream of this rejected boundary and were not executed. No corrected conformance/start/read call was constructed or run.'});
25:await save('retained-environment.json',{claim:'Read-only exact current prefix projection and actual successful Public catalog/view receipts; no new admission',projection,catalog,catalogView,readerInstalledRoot:identity.installedRoot,definitionContractCoordinates:(await read('bootstrap-core.json')).verifiedArtifact.definitionContractCoordinates,closeHandoff:failure.closeHandoff});
26:await save('final-handoff.json',failure.closeHandoff);
27:await save('runtime-slots.json',{installedProduct:projection.productInstalls.map(product.productInstallCoordinate)[0],admittedInstalls:projection.productInstalls,workspaceBinding:binding,workspaceAuthority:projection.workspaceAuthorityBasis,canonicalRoot:projection.workspaceAuthorityBasis.canonicalRoot,declaredRoots:(await read('setup-bind-stdout.json')).receipt.ownerOutput.value.declaredRoots,resolvedLock:{ref:projection.resolvedProductLock.lockId,digest:projection.resolvedProductLock.lockDigest},catalog:catalogReceipt.ownerOutput.value.catalog,catalogView:viewReceipt.ownerOutput.value.view,tenantManifest:null,executionSelectionRef:null,HelloRun:null,resourcePlan:plan,closeHandoff:failure.closeHandoff,reuse:'Current C02 resource and seven completed operations can be retained for a separately authorized caller-only continuation; no setup replay or subject relabel. No continuation authorized by this observation.',remaining:['Hello Program conformance','command-execution Program conformance','original Hello start','fresh run_result','fresh run_replay'],qualificationAuthority:'unbound; this observation is not a Product-owner ruling'});
28:await save('closed-resource-observation.json',{path:plan.eventLogPath,bytes:bytes.length,sha256:product.sha256Bytes(bytes).slice(7),device:after.dev,inode:after.ino,stable:true,failureSnapshotIdentical:true,unchangedSinceLastSuccessfulBindAndCatalog:true,lockPath,lockPresent,prefix:failure.closeHandoff.prefix,scope:'Only exact owned resource and lock; no hostwide process claim',nativeCallsInThisObserver:0});
29:console.log(JSON.stringify({status:'localized',extraKeys,lawEqual:true,inventoryCount:inventory.length,currentSelectionEqual:true,snapshotEqual:true,lockPresent:false,nativeCalls:0}));
